CREATE SCHEMA IF NOT EXISTS tenant;CREATE SCHEMA IF NOT EXISTS catalog;CREATE SCHEMA IF NOT EXISTS billing;CREATE SCHEMA IF NOT EXISTS fiscal;CREATE SCHEMA IF NOT EXISTS cms;CREATE SCHEMA IF NOT EXISTS support;CREATE SCHEMA IF NOT EXISTS product;CREATE SCHEMA IF NOT EXISTS ops;CREATE SCHEMA IF NOT EXISTS release;CREATE SCHEMA IF NOT EXISTS admin;CREATE SCHEMA IF NOT EXISTS ai_ops;
CREATE TABLE IF NOT EXISTS tenant.tenant(id uuid PRIMARY KEY DEFAULT uuidv7(),name text NOT NULL,kind text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',platform_organization_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog.plan_version(id uuid PRIMARY KEY DEFAULT uuidv7(),code text NOT NULL,version int NOT NULL,name text NOT NULL,currency char(3) NOT NULL DEFAULT 'BRL',monthly_cents bigint,annual_cents bigint,status text NOT NULL DEFAULT 'DRAFT',entitlements jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(code,version));
CREATE TABLE IF NOT EXISTS billing.subscription(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL REFERENCES tenant.tenant(id),plan_version_id uuid REFERENCES catalog.plan_version(id),provider text,provider_subscription_id text,status text NOT NULL DEFAULT 'PENDING',current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS billing.payment(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL REFERENCES tenant.tenant(id),provider text NOT NULL,provider_payment_id text,amount_cents bigint NOT NULL,currency char(3) NOT NULL DEFAULT 'BRL',status text NOT NULL,gross_cents bigint,fee_cents bigint,net_cents bigint,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_payment_id));
CREATE TABLE IF NOT EXISTS billing.webhook_event(id uuid PRIMARY KEY DEFAULT uuidv7(),provider text NOT NULL,event_key text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,error text,UNIQUE(provider,event_key));
CREATE TABLE IF NOT EXISTS billing.ledger_entry(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL REFERENCES tenant.tenant(id),kind text NOT NULL,amount_cents bigint NOT NULL,currency char(3) NOT NULL DEFAULT 'BRL',reference_type text,reference_id uuid,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cms.page(id uuid PRIMARY KEY DEFAULT uuidv7(),slug text NOT NULL UNIQUE,title text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',published_version_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cms.page_version(id uuid PRIMARY KEY DEFAULT uuidv7(),page_id uuid NOT NULL REFERENCES cms.page(id),version int NOT NULL,blocks jsonb NOT NULL DEFAULT '[]'::jsonb,seo jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(page_id,version));
CREATE TABLE IF NOT EXISTS product.feature_flag(id uuid PRIMARY KEY DEFAULT uuidv7(),code text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT false,configuration jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS release.release(id uuid PRIMARY KEY DEFAULT uuidv7(),version text NOT NULL,environment text NOT NULL,status text NOT NULL,artifact_digest text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(version,environment));
CREATE TABLE IF NOT EXISTS admin.audit_event(id uuid PRIMARY KEY DEFAULT uuidv7(),actor text NOT NULL,action text NOT NULL,object_type text,object_id text,before_data jsonb,after_data jsonb,reason text,created_at timestamptz NOT NULL DEFAULT now());
